pat_setup = re.compile(r'setup_timer\s*\(\s*[^,]+,\s*&?([A-Za-z_]\w*)')

def files_with(roots):
    res = subprocess.run(['grep', '-rlE', r'\.function\s*=|setup_timer\s*\(', *roots], capture_output=True, text=True)
    return res.stdout.split()

flist = files_with(['drivers', 'net'])

def find_def(src, name):
    # find definition like: static void NAME(...) or NAME(struct timer_list *t) etc.
    defs = [m.start() for m in re.finditer(r'(?m)^[^\n]*\b'+re.escape(name)+r'\s*\(', src)]
    return defs

results = []
for f in flist:
    path = os.path.join(root, f)
    try:
        src = open(path, errors='replace').read()
    except: continue
    names = set()
    for m in pat_assign.finditer(src):
        names.add(m.group(1))
    for m in pat_setup.finditer(src):
        names.add(m.group(1))
    for name in names:
        # find definition
        for d in find_def(src, name):
            # get line number
            line_no = src.count('\n', 0, d) + 1
            # extract body: from d find first '{' then brace-match
            i = src.find('{', d)
            if i < 0: continue
            depth = 0; j = i
            while j < len(src):
                c = src[j]
                if c == '{': depth += 1
                elif c == '}':
                    depth -= 1
                    if depth == 0: break
                j += 1
            body = src[i:j]
            locks = re.findall(r'spin_(?:un)?lock(?:_bh|_irq(?:save)?)?(?:_nested)??\s*\([^;]*', body)
            if locks:
                results.append((f, name, line_no, locks))
                break  # only first def

